Consider the following C code snippet. What will be the *possible* outputs, and why might the order vary?
```c
#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();
    if (pid == 0) { // Child process
        printf("Child: My PID is %d\n", getpid());
    } else if (pid > 0) { // Parent process
        wait(NULL);
        printf("Parent: My PID is %d, Child PID was %d\n", getpid(), pid);
    } else {
        perror("fork failed");
    }
    return 0;
}
```
